-- Planes. El id 1 es el plan gratuito que el frontend asigna al developer sin suscripcion activa (page-usuario).
-- Limites del plan gratuito iguales a subscription.service.ts del frontend: 3 repositorios y 2 proyectos.
-- Pro y Premium son planes de ejemplo del proyecto academico: ajusta precios y limites aqui.
-- Los planes son configuracion: en cada arranque se actualizan con los valores de este archivo.
INSERT INTO public.plan (id, name, description1, description2, description3, description4, maxnumberrepository, maxnumberproject, price, image, id_money) VALUES (1, 'Free', 'Perfil de developer', 'Postulación a ofertas de empleo', 'Portafolio visible para las empresas', NULL, 3, 2, 0, '/assets/imagenes/imagenPlan1.jpeg', 1) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description1 = EXCLUDED.description1, description2 = EXCLUDED.description2, description3 = EXCLUDED.description3, description4 = EXCLUDED.description4, maxnumberrepository = EXCLUDED.maxnumberrepository, maxnumberproject = EXCLUDED.maxnumberproject, price = EXCLUDED.price, image = EXCLUDED.image;
INSERT INTO public.plan (id, name, description1, description2, description3, description4, maxnumberrepository, maxnumberproject, price, image, id_money) VALUES (2, 'Pro', 'Todo lo del plan Free', 'Más repositorios y proyectos', NULL, NULL, 10, 20, 19.9, '/assets/imagenes/imagenPlan1.jpeg', 1) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description1 = EXCLUDED.description1, description2 = EXCLUDED.description2, description3 = EXCLUDED.description3, description4 = EXCLUDED.description4, maxnumberrepository = EXCLUDED.maxnumberrepository, maxnumberproject = EXCLUDED.maxnumberproject, price = EXCLUDED.price, image = EXCLUDED.image;
INSERT INTO public.plan (id, name, description1, description2, description3, description4, maxnumberrepository, maxnumberproject, price, image, id_money) VALUES (3, 'Premium', 'Todo lo del plan Pro', 'El límite más alto de repositorios y proyectos', NULL, NULL, 50, 100, 39.9, '/assets/imagenes/imagenPlan1.jpeg', 1) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description1 = EXCLUDED.description1, description2 = EXCLUDED.description2, description3 = EXCLUDED.description3, description4 = EXCLUDED.description4, maxnumberrepository = EXCLUDED.maxnumberrepository, maxnumberproject = EXCLUDED.maxnumberproject, price = EXCLUDED.price, image = EXCLUDED.image;
SELECT setval(pg_get_serial_sequence('public.plan', 'id'), (SELECT MAX(id) FROM public.plan));
